class RefundSweeper:
    """过期退款工单释放：expires_at <= now 触发退款并标记；
    已触发的工单不得重复触发。"""

    def __init__(self):
        self.tickets = []

    def register(self, tid, expires_at):
        self.tickets.append([tid, expires_at, False])

    def sweep(self, now):
        fired = []
        for tid, exp, _ in self.tickets:
            if exp <= now:
                fired.append(tid)
        return fired
